}

.schedule-cta .btn {
  background-color: var(--color-accent-dark);
  color: var(--color-bg);
  font-weight: 700;
  padding: var(--spacing-md) var(--spacing-lg);
}

.schedule-cta .btn:hover {
  background-color: var(--color-accent);
}

@media (max-width: 600px) {
  .schedule-day {
    padding: var(--spacing-lg) 0;
  }

  .schedule-table-wrapper {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .schedule-table {
    min-width: 500px;
  }

  .schedule-table th,
  .schedule-table td {
    padding: var(--spacing-sm);
    font-size: 0.85rem;
  }

  .schedule-cta {
    padding: var(--spacing-lg) 0;
  }

  .schedule-cta .btn {
    width: 100%;
    min-height: 48px;
  }
}

@media (min-width: 601px) {
  .schedule-day {
    padding: var(--spacing-xl) 0;
  }

  .schedule-table th,
  .schedule-table td {
    padding: var(--spacing-md);
  }
}

.speakers-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-bg);
  padding: var(--spacing-xxl) 0;
  text-align: center;
}

.speakers-hero h1 {
  color: var(--color-bg);
  margin-bottom: var(--spacing-md);
}

.speakers-intro {
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.speakers-filters {
  background-color: var(--color-bg-light);
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-border);
}

.speakers-filter-group {
  max-width: 400px;
}

.speakers-filter-group label {
  display: block;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
  color: var(--color-text);
}

.speakers-search {
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
}

.speakers-search:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-light);
}

.speakers-list {
  padding: var(--spacing-xxl) 0;
  background-color: var(--color-bg);
}

.speaker-card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.speaker-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.speaker-card-image {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: var(--radius);
  margin-bottom: var(--spacing-md);
}

.speaker-card-name {
  margin: var(--spacing-sm) 0;
  color: var(--color-primary-dark);
  font-size: 1.3rem;
}

.speaker-card-title {
  color: var(--color-primary);
  font-weight: 600;
  margin: var(--spacing-xs) 0;
  font-size: 0.95rem;
}

.speaker-card-company {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
  font-size: 0.9rem;
}

.speaker-card-topic {
  color: var(--color-text);
  margin: var(--spacing-sm) 0;
  font-size: 0.95rem;
}

.speaker-card-topic strong {
  color: var(--color-primary-dark);
}

.speaker-card-details {
  margin-top: auto;
  padding-top: var(--spacing-md);
}

.speaker-card-toggle {
  display: inline-block;
  background-color: var(--color-primary-light);
  color: var(--color-primary-dark);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius);
  cursor: pointer;
  font-weight: 600;
  font-size: 0.9rem;
  transition: background-color 0.2s ease;
  border: none;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.speaker-card-toggle:hover {
  background-color: var(--color-primary);
  color: var(--color-bg);
}

.speaker-card-toggle:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.speaker-card-bio {
  padding: var(--spacing-md) 0;
  color: var(--color-text-light);
  font-size: 0.95rem;
  line-height: 1.6;
}

.speaker-card-bio p {
  margin: var(--spacing-sm) 0;
}

.speakers-cta {
  background-color: var(--color-primary-light);
  padding: var(--spacing-xxl) 0;
  text-align: center;
  border-top: 1px solid var(--color-border);
}

.speakers-cta h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.speakers-cta p {
  font-size: 1.1rem;
  color: var(--color-text);
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 600px) {
  .speakers-hero {
    padding: var(--spacing-lg) 0;
  }

  .speakers-hero h1 {
    font-size: 1.5rem;
  }

  .speakers-intro {
    font-size: 1rem;
  }

  .speaker-card-image {
    height: 240px;
  }

  .speaker-card-toggle {
    width: 100%;
  }

  .speakers-list {
    padding: var(--spacing-lg) 0;
  }

  .speakers-cta {
    padding: var(--spacing-lg) 0;
  }

  .speakers-cta h2 {
    font-size: 1.25rem;
  }

  .speakers-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

.tickets-intro {
  background-color: var(--color-primary-light);
  padding: var(--spacing-lg) 0;
  margin-bottom: var(--spacing-xl);
}

.tickets-intro p {
  font-size: 1.05rem;
  margin-bottom: var(--spacing-md);
}

.tickets-pricing {
  padding: var(--spacing-xl) 0;
}

.tickets-subtitle {
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.tickets-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.tickets-card {
  border: 2px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  background-color: var(--color-bg);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  position: relative;
}

.tickets-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.tickets-card h3 {
  margin-top: 0;
  font-size: 1.5rem;
  margin-bottom: var(--spacing-sm);
}

.tickets-price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0 var(--spacing-xs) 0;
  line-height: 1;
}

.tickets-price-note {
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.tickets-description {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.tickets-features {
  list-style: none;
  padding: 0;
  margin: var(--spacing-md) 0;
  flex-grow: 1;
}

.tickets-features li {
  padding: var(--spacing-xs) 0;
  font-size: 0.95rem;
  color: var(--color-text);
}

.tickets-features li:last-child {
  margin-bottom: var(--spacing-md);
}

.tickets-card-standard {
  border-color: var(--color-border);
}

.tickets-card-featured {
  border-color: var(--color-primary-dark);
  border-width: 2px;
  box-shadow: var(--shadow-md);
  transform: scale(1.02);
}

.tickets-card-featured:hover {
  transform: scale(1.02) translateY(-4px);
}

.tickets-badge {
  position: absolute;
  top: -12px;
  left: 20px;
  background-color: var(--color-accent-dark);
  color: #030303;
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tickets-card-premium {
  border-color: var(--color-accent-dark);
}

.tickets-btn {
  width: 100%;
  margin-top: auto;
  min-height: 48px;
  font-size: 1rem;
}

.tickets-card-standard .tickets-btn {
  background-color: var(--color-primary-dark);
}

.tickets-card-featured .tickets-btn {
  background-color: var(--color-primary-dark);
}

.tickets-comparison {
  background-color: var(--color-bg-light);
  padding: var(--spacing-xl) 0;
  margin: var(--spacing-xxl) 0;
}

.tickets-table {
  margin-top: var(--spacing-lg);
  overflow-x: auto;
}

.tickets-table thead {
  background-color: var(--color-primary-dark);
}

.tickets-table th,
.tickets-table td {
  padding: var(--spacing-md);
  text-align: left;
  border-bottom: 1px solid var(--color-border);
}

.tickets-table th {
  font-weight: 700;
  color: var(--color-bg);
}

.tickets-table tbody tr:hover {
  background-color: #f0f6ff;
}

.tickets-table td:first-child {
  font-weight: 600;
  color: var(--color-primary-dark);
}

.tickets-faq {
  padding: var(--spacing-xl) 0;
}

.tickets-faq-item {
  margin: var(--spacing-lg) 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-md);
  background-color: var(--color-bg);
  cursor: pointer;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

.tickets-faq-item:hover {
  background-color: var(--color-primary-light);
  box-shadow: var(--shadow-sm);
}

.tickets-faq-item summary {
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--color-primary-dark);
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
}

.tickets-faq-item summary::-webkit-details-marker {
  display: none;
}

.tickets-faq-item summary::after {
  content: '+';
  font-size: 1.5rem;
  font-weight: 300;
  margin-left: var(--spacing-md);
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

.tickets-faq-item[open] summary::after {
  transform: rotate(45deg);
}

.tickets-faq-item p {
  margin: var(--spacing-md) 0 0 0;
  color: var(--color-text);
}

.tickets-checkout {
  background-color: var(--color-primary-light);
  padding: var(--spacing-xl) 0;
  text-align: center;
  margin-top: var(--spacing-xl);
}

.tickets-checkout p {
  font-size: 1.05rem;
  margin: var(--spacing-md) 0;
}

/* Responsive Design */
@media (max-width: 600px) {
  .tickets-grid {
    grid-template-columns: 1fr;
  }

  .tickets-card-featured {
    transform: scale(1);
  }

  .tickets-card-featured:hover {
    transform: translateY(-4px);
  }

  .tickets-price {
    font-size: 2rem;
  }

  .tickets-badge {
    top: 10px;
    left: 10px;
    right: 10px;
    width: auto;
  }

  .tickets-card {
    padding: var(--spacing-md);
  }

  .tickets-table {
    font-size: 0.85rem;
  }

  .tickets-table th,
  .tickets-table td {
    padding: var(--spacing-sm);
  }

  .tickets-faq-item {
    padding: var(--spacing-sm);
    margin: var(--spacing-md) 0;
  }

  .tickets-faq-item summary {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .tickets-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .tickets-table {
    display: table;
  }
}
